import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
} from '@angular/core';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { ActivatedRoute } from '@angular/router';
import { PresentsetupService } from '../../../services/presentsetup/presentsetup.service';
import { presentScheduleList } from '../../../interfaces/presentsetup';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { MatMenuModule } from '@angular/material/menu';
import { EmptyComponent } from '../../../../shared/components/empty/empty.component';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { LocationStrategy } from '@angular/common';
import { HeaderService } from '../../../../core/services/header/header.service';
import { UserPermissionService } from '../../../../shared/services/user-permission/user-permission.service';

@Component({
  selector: 'app-schedule-list',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './schedule-list.component.html',
  styleUrl: './schedule-list.component.scss',
  imports: [
    ButtonComponent,
    MatMenuModule,
    EmptyComponent,
    IconComponent,
    AvatarComponent,
  ],
})
export class ScheduleListComponent {
  nCaseid: string;
  scheduleList: presentScheduleList[] = [];

  constructor(
    private PSservice: PresentsetupService,
    private cm: CommonfunctionService,
    private route: ActivatedRoute,
    private cdr: ChangeDetectorRef,
    private location: LocationStrategy,
    private hs: HeaderService,
    private userPermissions: UserPermissionService
  ) {
    var params = this.route.snapshot.params;
    params = JSON.parse(decodeURIComponent(params['id']));
    this.nCaseid = params && params['id'] ? params['id'] : '';
    hs.nCaseid = this.nCaseid;

    // disable window history
    history.pushState(null, null, window.location.href);
    this.location.onPopState(() => {
      history.pushState(null, null, window.location.href);
    });
        userPermissions.userPermissionList(this.nCaseid);

  }

  async ngOnInit() {
    if (!this.nCaseid) {
      this.cm.gotoUrl('/user/dashboard');
    }
    await this.getScheduleList();
  }

  async getScheduleList() {
    this.scheduleList = await this.PSservice.scheduleList(this.nCaseid);
    if (this.scheduleList.length == 0) {
      this.cm.gotoUrl('/present/createWitness', { id: this.nCaseid });
    }
    this.cdr.detectChanges();
  }

  setup() {
    // this.cm.gotoUrl('/present/createWitness', { id: this.nCaseid });

    this.cm.gotoUrl('/present/setup', { id: this.nCaseid, type: 'W' });
  }

  async deleteSchedule(nPCid: string, index) {
    const res = await this.PSservice.deleteSchedule(nPCid);
    if (res.msg == 1) {
      this.scheduleList.splice(index, 1);
      this.cdr.detectChanges();
    }
  }
  viewSchedule(nPresentid: string) {
    this.cm.gotoUrl('/present/core-case', {
      id: this.nCaseid,
      nPid: nPresentid,
    });
  }

  editSchedule(x: presentScheduleList) {
    this.cm.gotoUrl('/present/createWitness', {
      id: this.nCaseid,
      nCid: x.nContactid,
      nPid: x.nPresentid,
      nPCid: x.nPCid,
    });
  }
}
